function water(kg, exerciseMin, hot){
  var base = kg*33; // mL
  var add = Math.floor(exerciseMin/30)*500;
  if(hot) add += 500;
  return base + add;
}
var EXPORTS={water:water};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.WaterIntakeForgePure = EXPORTS; }
